[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/odrlagreement/no-assignee> ;
            sh:resultMessage "This kind of ODRL policy needs an assignee: give odrl:assignee at policy level, or on every permission and prohibition (N7a7effffca77444692de430b42befd06 has none)." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint cdifd:policyHasAssignee ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape cdifd:ODRLAgreementShape ;
            sh:value <https://example.org/odrlagreement/no-assignee> ] .

